DELETE FROM alarm_channel_binding
WHERE owner_type = #{ownerType}
  AND owner_id = #{ownerId}

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM alarm_channel_binding
    WHERE channel_id = #{channelId}
)

SELECT owner_type, owner_id, channel_id
FROM alarm_channel_binding
WHERE owner_type = #{ownerType}
  AND owner_id = #{ownerId}
ORDER BY channel_id
